import{_ as a,o as p,a as n,b as l}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"数据搬运导览","link":"/api/SIMD-API/basic_api/data_move_guide/data_move_guide"},{"text":"UB与UB数据搬运","link":"/api/SIMD-API/basic_api/data_move_guide/UB_UB_data_move"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/data_move_guide/UB_UB_data_move.md","filePath":"api/SIMD-API/basic_api/data_move_guide/UB_UB_data_move.md","outlineHeaders":[{"level":2,"title":"总体说明","slug":"总体说明","link":"#总体说明"},{"level":2,"title":"DataCopy（UB -> UB连续数据搬运）","slug":"DataCopy（UB-->-UB连续数据搬运）","link":"#DataCopy（UB-->-UB连续数据搬运）"},{"level":2,"title":"DataCopy（UB -> UB高维切分数据搬运）","slug":"DataCopy（UB-->-UB高维切分数据搬运）","link":"#DataCopy（UB-->-UB高维切分数据搬运）"},{"level":2,"title":"Copy（UB -> UB连续数据搬运）","slug":"Copy（UB-->-UB连续数据搬运）","link":"#Copy（UB-->-UB连续数据搬运）"},{"level":2,"title":"Copy（UB -> UB掩码式高维数据搬运）","slug":"Copy（UB-->-UB掩码式高维数据搬运）","link":"#Copy（UB-->-UB掩码式高维数据搬运）"}],"lastUpdated":1787050286000}'),c={name:"api/SIMD-API/basic_api/data_move_guide/UB_UB_data_move.md"};function t(e,s,o,i,d,r){return p(),n("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>UB与UB数据搬运<span id="ZH-CN_TOPIC_0000001499154365"></span></h1><h2 id="总体说明">总体说明<span id="ZH-CN_TOPIC_0000002574022829"></span><a class="header-anchor" href="#总体说明">​</a></h2><p>Unified Buffer（UB）之间的数据搬运提供了灵活的接口支持，共有两组接口：DataCopy提供了基础的数据搬运能力，支持连续和非连续数据搬运；Copy除了支持连续和非连续数据搬运，还提供了mask操作和DataBlock间隔操作的能力，支持在接口内部和接口外部设置mask。具体接口功能如下表所示。</p><p><strong>表 1</strong> UB与UB数据搬运接口概述</p><p><span id="zh-cn_topic_0000002568294885_table12546123753110"></span></p><table><thead><tr><th align="center">数据通路</th><th align="left">功能</th><th align="left">描述</th></tr></thead><tbody><tr><td align="center">UB-&gt;UB</td><td align="left">连续数据搬运(DataCopy)</td><td align="left">提供基础的数据搬运能力，数据在传输过程中保持原始格式和内容不变，支持连续数据搬运。</td></tr><tr><td align="center">UB-&gt;UB</td><td align="left">高维切分数据搬运(DataCopy)</td><td align="left">提供基础的数据搬运能力，数据在传输过程中保持原始格式和内容不变，支持连续和非连续的数据搬运。</td></tr><tr><td align="center">UB-&gt;UB</td><td align="left">连续数据搬运(Copy)</td><td align="left">支持连续数据搬运，数据搬运时格式和内容保持不变。</td></tr><tr><td align="center">UB-&gt;UB</td><td align="left">掩码式高维数据搬运(Copy)</td><td align="left">支持mask操作和DataBlock间隔操作，支持在接口内部和接口外部设置mask。</td></tr></tbody></table><h2 id="DataCopy（UB--&gt;-UB连续数据搬运）">DataCopy（UB -&gt; UB连续数据搬运）<span id="ZH-CN_TOPIC_0000002382907025"></span><a class="header-anchor" href="#DataCopy（UB--&gt;-UB连续数据搬运）">​</a></h2><p>支持UB与UB之间的连续数据搬运，数据在传输过程中保持原始格式和内容不变。</p><p>具体支持的数据通路为（以<a href="../../basic_api/aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li>UB -&gt; UB <ul><li>VECIN -&gt; VECCALC</li><li>VECCALC -&gt; VECOUT</li></ul></li></ul><p>搬运的数据用于<a href="../memory_vector_compute/memory_vector_compute.html">矢量计算</a>，具体的接口请参考：<a href="../memory_vector_compute/data_move/DataCopy_UBToUB_continuous.html">DataCopy（UB -&gt; UB连续数据搬运）</a>。</p><p>src和dst分别为源操作数和目的操作数；count为连续搬运的元素个数。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>
</code></pre></div><h2 id="DataCopy（UB--&gt;-UB高维切分数据搬运）">DataCopy（UB -&gt; UB高维切分数据搬运）<span id="ZH-CN_TOPIC_0000002382908321"></span><a class="header-anchor" href="#DataCopy（UB--&gt;-UB高维切分数据搬运）">​</a></h2><p>支持UB与UB之间的高维切分数据搬运，数据在传输过程中保持原始格式和内容不变。</p><p>高维切分数据搬运可通过配置数据块个数、单个数据块长度、地址偏移等搬运参数，同时支持非连续和连续的数据搬运。</p><p>具体支持的数据通路为（以<a href="../../basic_api/aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li>UB -&gt; UB <ul><li>VECIN -&gt; VECCALC</li><li>VECCALC -&gt; VECOUT</li></ul></li></ul><p>搬运的数据用于<a href="../memory_vector_compute/memory_vector_compute.html">矢量计算</a>，具体的接口请参考：<a href="../memory_vector_compute/data_move/DataCopy_UBToUB_highdim_split.html">DataCopy（UB -&gt; UB高维切分数据搬运）</a>。</p><p>src和dst分别为源操作数和目的操作数；repeatParams为DataCopyParams类型的搬运参数，通过该参数可配置搬运的数据块大小、个数、间隔等信息，同时支持非连续和连续搬运。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">DataCopyParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">)</span>
</code></pre></div><h2 id="Copy（UB--&gt;-UB连续数据搬运）">Copy（UB -&gt; UB连续数据搬运）<span id="ZH-CN_TOPIC_0000002575088175"></span><a class="header-anchor" href="#Copy（UB--&gt;-UB连续数据搬运）">​</a></h2><p>支持UB和UB之间的连续数据搬运，数据搬运时格式和内容保持不变。</p><p>具体支持的数据通路为（以<a href="../../basic_api/aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li>UB -&gt; UB <ul><li>VECIN -&gt; VECCALC</li><li>VECIN -&gt; VECOUT</li><li>VECCALC -&gt; VECIN</li><li>VECCALC -&gt; VECOUT</li><li>VECOUT -&gt; VECIN</li><li>VECOUT -&gt; VECCALC</li></ul></li></ul><p>搬运的数据用于<a href="../memory_vector_compute/memory_vector_compute.html">矢量计算</a>，具体的接口请参考：<a href="../memory_vector_compute/data_move/Copy_UBToUB_continuous.html">Copy（UB -&gt; UB连续数据搬运）</a>。</p><p>src和dst分别为源操作数和目的操作数；count为连续搬运的元素个数。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">isSetMask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>
</code></pre></div><h2 id="Copy（UB--&gt;-UB掩码式高维数据搬运）">Copy（UB -&gt; UB掩码式高维数据搬运）<span id="ZH-CN_TOPIC_0000002575088676"></span><a class="header-anchor" href="#Copy（UB--&gt;-UB掩码式高维数据搬运）">​</a></h2><p>支持UB和UB之间的数据搬运，数据搬运时格式和内容保持不变，支持mask操作和DataBlock间隔操作。</p><p>具体支持的数据通路为（以<a href="../../basic_api/aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li>UB -&gt; UB <ul><li>VECIN -&gt; VECCALC</li><li>VECIN -&gt; VECOUT</li><li>VECCALC -&gt; VECIN</li><li>VECCALC -&gt; VECOUT</li><li>VECOUT -&gt; VECIN</li><li>VECOUT -&gt; VECCALC</li></ul></li></ul><p>搬运的数据用于<a href="../memory_vector_compute/memory_vector_compute.html">矢量计算</a>，具体的接口请参考：<a href="../memory_vector_compute/data_move/Copy_UBToUB_mask_highdim_split.html">Copy（UB -&gt; UB掩码式高维数据搬运）</a>。</p><p>src和dst分别为源操作数和目的操作数；mask用于控制每次迭代内参与计算的元素；repeatTime为重复迭代次数；repeatParams为CopyRepeatParams类型的搬运参数。</p><ul><li><p>mask逐bit模式</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">isSetMask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="p">[],</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeatTime</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">CopyRepeatParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">)</span>
</code></pre></div></li><li><p>mask连续模式</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">isSetMask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeatTime</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">CopyRepeatParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">repeatParams</span><span class="p">)</span>
</code></pre></div></li></ul></article></div>`,1)])])}const C=a(c,[["render",t]]);export{_ as __pageData,C as default};
